// AntigravityContextResponse composes with P2 ObserverResponse after local
// process/capability verification. Only PreInvocation injects, which also runs
// on exact resume. The root must persist a per-launch/process/conversation
// delivery receipt and suppress duplicate event execution before calling this.
// A response is prepared delivery, not proof the model loaded the context.
func AntigravityContextResponse(c AntigravityContext, event string, observer json.RawMessage) (json.RawMessage, error) {
	if err := c.Validate(); err != nil {
		return nil, err
	}
	var response map[string]json.RawMessage
	if err := json.Unmarshal(observer, &response); err != nil || response == nil {
		return nil, ErrSquadContextUnavailable
	}
	if _, exists := response["injectSteps"]; exists {
		return nil, ErrSquadContextUnavailable
	}
	if event != "PreInvocation" || c.Instructions() == "" {
		return observer, nil
	}
	step := map[string]any{"systemMessage": map[string]string{"systemMessage": c.Instructions()}}
	encoded, err := json.Marshal([]any{step})
	if err != nil {
		return nil, err
	}
	response["injectSteps"] = encoded
	return json.Marshal(response)
}

func (c *Client) prompt(ctx context.Context, text, uri, contextText string, before func() error, written func()) (PromptResult, error) {
	if !c.callMu.TryLock() {
		return PromptResult{}, failure("busy", NotWritten)
	}
	defer c.callMu.Unlock()
	if !c.authenticated || c.SessionID() == "" {
		return PromptResult{}, failure("not_ready", NotWritten)
	}
	if err := c.checkPersonal(); err != nil {
		return PromptResult{}, err
	}
	prompt := []any{map[string]string{"type": "text", "text": text}}
	if contextText != "" {
		if !c.embeddedContext {
			return PromptResult{}, failure("embedded_context_unsupported", NotWritten)
		}
		u, err := url.Parse(uri)
		if err != nil || u.Scheme != "file" || u.Host != "" || !filepath.IsAbs(u.Path) || u.RawQuery != "" || u.Fragment != "" {
			return PromptResult{}, failure("invalid_context_uri", NotWritten)
		}
		prompt = append([]any{map[string]any{"type": "resource", "resource": map[string]string{"uri": uri, "mimeType": "text/plain", "text": contextText}}}, prompt...)
	}
	r, err := c.exchange(ctx, "session/prompt", map[string]any{"sessionId": c.SessionID(), "prompt": prompt}, before, written, 0)
	if err != nil {
		return PromptResult{}, err
	}
	m, err := object(r)
	var stop string
	if err != nil || json.Unmarshal(m["stopReason"], &stop) != nil || stop == "" {
		return PromptResult{}, c.badResult("invalid_stop_reason")
	}
	return PromptResult{StopReason: stop, Raw: r}, nil
}

